{
  "Q1": {
    "q1a_rule": {
      "verdict": "yes",
      "rationale": "Gives FR Doc. 2026-15665, 91 FR 49178-49227, published August 3, 2026, effective September 2, 2026, docket OPM-2025-0107, RIN 3206-AO86."
    },
    "q1b_nprm": {
      "verdict": "yes",
      "rationale": "Identifies FR Doc. 2026-04377, 91 FR 10904, published March 5, 2026."
    },
    "q1c_first": {
      "verdict": "yes",
      "rationale": "Lists 2026-17335, published August 25, 2026, effective September 2, 2026, and describes it as correcting typographical and clerical errors in amendatory instructions and regulatory text."
    },
    "q1c_second": {
      "verdict": "yes",
      "rationale": "Lists 2026-18800, published and effective September 15, 2026, restoring paragraphs (1)(i) and (1)(ii) of the definition of 'displaced' in 5 CFR 330.602 after instruction 11 inadvertently removed them."
    },
    "q1d_applicability": {
      "verdict": "yes",
      "rationale": "Correctly makes the notice-issuance date the test: notices before September 2, 2026 stay under the prior rules, notices on or after that date use the amended rules; locates this in the DATES line and the Implementation Considerations preamble section at 91 FR 49178, 49206-07."
    },
    "q1e_appeals": {
      "verdict": "yes",
      "rationale": "Lists 2026-15666, effective September 2, 2026 and in force, replacing subpart I (351.901-351.909) of part 351."
    },
    "q1e_leave": {
      "verdict": "yes",
      "rationale": "Lists 2026-21320, says it revises 351.806, gives effective date November 18, 2026, and says it is not yet in force on November 14, 2026."
    },
    "q1e_senior": {
      "verdict": "yes",
      "rationale": "Lists 2026-21316, says it revises the 351.203 definition of 'Rating of record,' gives effective date November 18, 2026, and says it is not yet in force."
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "The answer repeatedly cites FR documents, CFR paragraphs and FR pages; no substantial citation-discipline failure."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "No invented document, citation or quotation. The extra 2026-21319 reference is a real time-in-grade final rule."
    }
  },
  "Q2": {
    "q2a_abbott": {
      "verdict": "yes",
      "rationale": "Abbott: 7+5+5=17, no veterans' points, total 17."
    },
    "q2a_bianchi": {
      "verdict": "yes",
      "rationale": "Bianchi: 5+0+3=8 because Level 2 is 0, plus 5 veterans' points, total 13."
    },
    "q2a_castillo": {
      "verdict": "yes",
      "rationale": "Castillo: 7+5+5=17 and 0 veterans' points; correctly reasons that a retired member with 20+ years of length-of-service retired pay and no qualifying disability retirement is not preference eligible under 351.504(b)."
    },
    "q2a_dalton": {
      "verdict": "yes",
      "rationale": "Dalton: two ratings, proxy (7+0)/2=3.5, performance credit 10.5, plus 3, total 13.5."
    },
    "q2a_eze": {
      "verdict": "yes",
      "rationale": "Eze: performance credit 5+5+5=15, no veterans' points, total 15, and placed in tenure subgroup II because he is not a career employee."
    },
    "q2a_fontaine": {
      "verdict": "yes",
      "rationale": "Fontaine: one rating, 5 x 3 = 15, total 15."
    },
    "q2b_order": {
      "verdict": "yes",
      "rationale": "Gives Abbott, Castillo, Fontaine, Eze, Dalton, Bianchi and explains both ties: Abbott over Castillo by earlier SCD, and Fontaine over Eze because tenure subgroup I outranks II."
    },
    "q2b_released": {
      "verdict": "yes",
      "rationale": "Says the two released employees are Bianchi and Dalton."
    },
    "q2c_old": {
      "verdict": "yes",
      "rationale": "Says Bianchi would stand above Abbott under the earlier rules because the 2026 final rule describes ranking by tenure group, then veterans' preference subgroup AD/A/B, and only then adjusted service date; cites 91 FR 49198."
    },
    "q2d_records": {
      "verdict": "yes",
      "rationale": "Says 351.506 entitles a noticed employee to inspect the complete retention register, including other employees' names, performance credit as augmented by veterans' preference, and SCDs, plus other relevant registers."
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "The answer cites CFR paragraphs and FR pages throughout."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "The FOIA/Privacy Act reference to 351.506(e) is real; no invented source or quotation."
    }
  },
  "Q3": {
    "q3a_case_a": {
      "verdict": "yes",
      "rationale": "Case A: not preference eligible, 0 points, subgroup B, under 351.504(b)."
    },
    "q3a_case_b": {
      "verdict": "yes",
      "rationale": "Case B: not preference eligible, 0 points, subgroup B; correctly applies 351.504(b)(4) to a Navy commander at major-equivalent rank."
    },
    "q3a_case_c": {
      "verdict": "yes",
      "rationale": "Case C: preference eligible, +5, subgroup AD under 351.504(b)(1)(i), (b)(4), and 351.504(a)(1)."
    },
    "q3a_case_d": {
      "verdict": "yes",
      "rationale": "Case D: not preference eligible, 0 points, subgroup B, because retired pay is based on 20+ years and no other condition is met."
    },
    "q3a_case_e": {
      "verdict": "yes",
      "rationale": "Case E: preference eligible because retired pay is not based on 20+ years and he is below major, so +3, subgroup A."
    },
    "q3b_scd_a": {
      "verdict": "yes",
      "rationale": "Employee A: only the 2 campaign years count; September 7, 2010 minus 2 years = September 7, 2008."
    },
    "q3b_scd_c": {
      "verdict": "yes",
      "rationale": "Employee C: all 14 years count because he is preference eligible; September 7, 2010 minus 14 years = September 7, 1996."
    },
    "q3c_labels": {
      "verdict": "yes",
      "rationale": "Says AD/A/B are register and notice labels, not a ranking step or tiebreaker; preference operates through the 5 or 3 points added to performance credit."
    },
    "q3_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant CFR paragraphs and FR pages."
    },
    "q3_fab": {
      "verdict": "no",
      "rationale": "The 351.504(b)(5) chapter 67 reference is real; no fabricated source."
    }
  },
  "Q4": {
    "q4a_farah": {
      "verdict": "yes",
      "rationale": "Farah: 7+3+3=13 using the three most recent ratings."
    },
    "q4b_cutoff_date": {
      "verdict": "yes",
      "rationale": "Cutoff date July 20, 2026, 45 days before September 3, 2026."
    },
    "q4b_credit": {
      "verdict": "yes",
      "rationale": "With the cutoff, Farah's credit is 3+3+5=11; the August 10, 2026 rating is excluded."
    },
    "q4c_not_on_record": {
      "verdict": "yes",
      "rationale": "Says the rating cannot be used because it was not on record until August 15, after the July 20 cutoff, citing 351.503(c)(2)-(3)."
    },
    "q4d_gina": {
      "verdict": "yes",
      "rationale": "Gina: August 15, 2022 is outside the period; two ratings 5 and 3, proxy 4, credit 5+3+4=12."
    },
    "q4e_modal": {
      "verdict": "yes",
      "rationale": "Says Hank's credit must be based on the modal rating for the applicable summary-level pattern under 351.503(f)(1)."
    },
    "q4e_flag": {
      "verdict": "yes",
      "rationale": "Flags that the 2026 documents do not print the 351.203 modal-rating definition and give no conversion formula; the suggested 9 is expressly hypothetical."
    },
    "q4_cite": {
      "verdict": "no",
      "rationale": "The answer cites 351.503 paragraphs and the relevant FR pages."
    },
    "q4_fab": {
      "verdict": "no",
      "rationale": "No fabricated citation or quotation."
    }
  },
  "Q5": {
    "q5a_i_rules": {
      "verdict": "yes",
      "rationale": "Says the August 28, 2026 notice is under the earlier rules because the notice preceded September 2, notwithstanding the October 27 effective date."
    },
    "q5a_i_result": {
      "verdict": "yes",
      "rationale": "Uses the final rule's description of the earlier rules (20 years for Level 5, 16 for Level 4, 12 for Level 3) and computes Lee 1986, Park 1999, so Park is released."
    },
    "q5a_ii": {
      "verdict": "yes",
      "rationale": "September 2, 2026 is on the effective date, so the amended rules apply; Lee 9, Park 21, Lee released."
    },
    "q5a_iii": {
      "verdict": "yes",
      "rationale": "September 3, 2026 is under the amended rules; Lee is released."
    },
    "q5b_no_recalc": {
      "verdict": "yes",
      "rationale": "Says no recalculation, citing 351.805(b): an amended notice solely stating a later effective date is not a new specific RIF notice for 351.507."
    },
    "q5c_version": {
      "verdict": "yes",
      "rationale": "Version is fixed by the date the agency issues the RIF notice, per the DATES line and implementation section."
    },
    "q5c_window": {
      "verdict": "yes",
      "rationale": "Four-year ratings window ends at issuance of the RIF notices, or the agency cutoff if one is used (351.503(c)(1)-(2))."
    },
    "q5c_standing": {
      "verdict": "yes",
      "rationale": "Tenure subgroup and retention standing are fixed when the employee receives the specific RIF notice, citing 351.502 and 351.507(a)."
    },
    "q5_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant documents and CFR paragraphs."
    },
    "q5_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation."
    }
  },
  "Q6": {
    "q6a_reach": {
      "verdict": "yes",
      "rationale": "Treats positions 1, 2 and 3 as within reach and rules out 4 (four grades down), 5 (higher standing), 6 (part-time schedule) and 7 (different competitive area) under 351.701."
    },
    "q6a_offer": {
      "verdict": "yes",
      "rationale": "Says the agency must offer position 1, the GS-12 held by Ellis, as the least reduction in representative rate."
    },
    "q6b_five": {
      "verdict": "yes",
      "rationale": "Says the grade limit becomes five grades, so position 4 (GS-9) is also within reach, but the offer remains position 1."
    },
    "q6c_level1": {
      "verdict": "yes",
      "rationale": "Says a Level 1 current rating gives no assignment right because 351.701(a) requires Level 2 or higher."
    },
    "q6d_excepted": {
      "verdict": "yes",
      "rationale": "Says 351.701 covers competitive service; excepted service assignment rights exist only if the agency adopts them under 351.705(a)."
    },
    "q6e_level2": {
      "verdict": "yes",
      "rationale": "Says the former 351.701(d) restriction on Level 2 employees taking positions held by higher-rated employees was eliminated (91 FR 49204)."
    },
    "q6e_bump": {
      "verdict": "yes",
      "rationale": "Says the final rule replaced bump and retreat with a single assignment right to a position held by a lower-standing employee (91 FR 49204)."
    },
    "q6_cite": {
      "verdict": "no",
      "rationale": "The answer cites 351.701, 351.705 and the relevant FR pages."
    },
    "q6_fab": {
      "verdict": "no",
      "rationale": "No fabricated source. The reference to 351.701(d) is to a real former provision."
    }
  },
  "Q7": {
    "q7a_mspb": {
      "verdict": "yes",
      "rationale": "Concludes the MSPB hears the appeal because the specific notice was issued August 31, 2026, before the September 2 applicability date; distinguishes the October 30 separation date."
    },
    "q7a_board_rule": {
      "verdict": "yes",
      "rationale": "Cites FR Doc. 2026-16456, 91 FR 51997, and says the Board will accept RIF appeals where the RIF notice was issued before September 2, 2026."
    },
    "q7b_opm": {
      "verdict": "yes",
      "rationale": "Says the appeal goes to OPM under 351.901(a)."
    },
    "q7b_count": {
      "verdict": "yes",
      "rationale": "Counts day 1 as December 19, 2026, day 30 as Sunday January 17, 2027, and applies the first-workday rule."
    },
    "q7b_date": {
      "verdict": "yes",
      "rationale": "Gives Tuesday, January 19, 2027, because Monday January 18 is Martin Luther King Jr. Day."
    },
    "q7b_efile": {
      "verdict": "yes",
      "rationale": "Requires electronic filing through OPM's system and gives 11:59 p.m. Eastern Time on the last day."
    },
    "q7c_burden": {
      "verdict": "yes",
      "rationale": "States the employee's preponderance burden to show a RIF statute/regulation violation and prejudice under 351.901(b)."
    },
    "q7c_hearing": {
      "verdict": "yes",
      "rationale": "Says there is no hearing as of right; review is on the written record unless OPM finds a hearing necessary and efficient under 351.905(c)."
    },
    "q7d_text": {
      "verdict": "yes",
      "rationale": "Says 351.901(c)(1)-(2) makes the OPM process exclusive and bars raising the RIF under a negotiated grievance procedure or grievance arbitration."
    },
    "q7d_flag": {
      "verdict": "yes",
      "rationale": "Reports the preamble's existing-CBA caveat: the rule does not retroactively invalidate existing CBAs and limits bargaining when agreements are renegotiated (91 FR 49245)."
    },
    "q7e_court": {
      "verdict": "yes",
      "rationale": "Says no judicial review under 351.901(c)(4) and no further appeal from OPM's final decision under 351.909(e)."
    },
    "q7f_tolling": {
      "verdict": "yes",
      "rationale": "Says she may still appeal under 351.902(b)(3), by April 9, 2027, 30 days after the March 10, 2027 final OSC decision."
    },
    "q7g_where": {
      "verdict": "yes",
      "rationale": "Places the applicability rule in the DATES paragraph of 2026-15666 at 91 FR 49230 and does not attribute it to 351.901's regulatory text."
    },
    "q7_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant FR documents and CFR paragraphs."
    },
    "q7_fab": {
      "verdict": "no",
      "rationale": "The quoted DATES language is accurate; no invented source."
    }
  },
  "Q8": {
    "q8a_adopted": {
      "verdict": "yes",
      "rationale": "Identifies 2026-21320 as revising 351.806, effective November 18, 2026, and says it is not in force on November 14, 2026."
    },
    "q8a_new_text": {
      "verdict": "yes",
      "rationale": "Gives the adopted text: ordinary duty status, and administrative leave for all or part of the notice period when appropriate and consistent with part 630, subpart N."
    },
    "q8a_today": {
      "verdict": "yes",
      "rationale": "Says the current version keeps the employee in duty status 'when possible,' as the rulemaking describes it (91 FR 65926, 65933)."
    },
    "q8b_consent": {
      "verdict": "yes",
      "rationale": "Says no consent is required, citing 351.806(b), 5 CFR 630.1403(c)(10), and the preamble's with-or-without-consent statement."
    },
    "q8b_cap": {
      "verdict": "yes",
      "rationale": "Says the adopted text states no numeric cap for administrative leave during a RIF notice period under 630.1403(c)(10)."
    },
    "q8b_12wk": {
      "verdict": "yes",
      "rationale": "Discusses the governmentwide 12-week workforce-realignment limit and notes the 10-workday limit applies to investigative leave, not this use."
    },
    "q8b_flag": {
      "verdict": "yes",
      "rationale": "Flags that whether the 12-week governmentwide limit reaches (c)(10) is not stated and that the adopted text was not yet in force when the leave began."
    },
    "q8c_guidance": {
      "verdict": "yes",
      "rationale": "Cites OPM's Template for Agency Administrative Leave Policies, CPM 2025-12, July 30, 2025, section D.1.b, and 91 FR 65926."
    },
    "q8d_no_effect": {
      "verdict": "yes",
      "rationale": "Says administrative leave does not change retention standing, registers, veterans' preference, RIF requirements or appeal rights (91 FR 65925-26)."
    },
    "q8_cite": {
      "verdict": "no",
      "rationale": "The answer cites the CFR provisions and FR pages."
    },
    "q8_fab": {
      "verdict": "no",
      "rationale": "The CPM number, section and quoted text are real."
    }
  },
  "Q9": {
    "q9_s1": {
      "verdict": "yes",
      "rationale": "Step 1 noncompliant: 57 days is within 90 days, so 351.402(c) required submission of the competitive-area description and bona fide organizational basis to OPM for approval in advance."
    },
    "q9_s3": {
      "verdict": "yes",
      "rationale": "Step 3 noncompliant: the 351.203 initial-probationary-period definition excludes supervisory or managerial probation, so Ortiz is a competing employee and had to be ranked."
    },
    "q9_s4": {
      "verdict": "yes",
      "rationale": "Step 4 noncompliant: cutoff was September 13, 2026, so the October 2 rating could not be put on record and used after the cutoff; the answer also notes uniformity."
    },
    "q9_s5": {
      "verdict": "yes",
      "rationale": "Step 5 noncompliant: proxy is (7+5)/2=6, so Quist's credit is 18, not 15."
    },
    "q9_s6": {
      "verdict": "yes",
      "rationale": "Step 6 noncompliant: 351.503(d) permits additional points only for single patterns whose highest level is Level 3; a five-level pattern gets the standard credit, and advance policy language does not cure it."
    },
    "q9_s8": {
      "verdict": "yes",
      "rationale": "Step 8 noncompliant: 351.602(a) bars releasing a competing employee while retaining an employee on a specifically limited temporary or term promotion."
    },
    "q9_s10": {
      "verdict": "yes",
      "rationale": "Step 10 noncompliant: 351.702(a)(4)(i)-(iii) requires a job-analysis-based assessment allowing demonstration of job-related skills and not solely or principally an automated self-assessment."
    },
    "q9_s11": {
      "verdict": "yes",
      "rationale": "Step 11 noncompliant: 351.608(a)(3) bars sequencing or stacking exceptions; only the single exception giving the longest period may be used."
    },
    "q9_s12": {
      "verdict": "yes",
      "rationale": "Step 12 noncompliant: for notices issued on or after September 2, 2026, appeal is to OPM under part 351, subpart I, not MSPB."
    },
    "q9_ok": {
      "verdict": "yes",
      "rationale": "Says steps 2, 7 and 9 are in order and gives the controlling provisions for all three: 351.202(d)(2)-(3), 351.601(c), and 351.702(a)(4)(v)."
    },
    "q9_false2": {
      "verdict": "no",
      "rationale": "The answer correctly treats step 2 as in order."
    },
    "q9_false7": {
      "verdict": "no",
      "rationale": "The answer correctly treats step 7 as in order."
    },
    "q9_false9": {
      "verdict": "no",
      "rationale": "The answer correctly treats step 9 as in order."
    },
    "q9_cite": {
      "verdict": "no",
      "rationale": "The answer cites the governing CFR paragraphs and FR pages for each step."
    },
    "q9_fab": {
      "verdict": "no",
      "rationale": "No invented provision or document. The 351.402(b)(1) and 351.608(g) references are real."
    }
  },
  "Q10": {
    "q10a_gap": {
      "verdict": "yes",
      "rationale": "Says that on September 10, 2026 paragraph (1) contained only its introductory text and that (1)(i)-(ii) were missing because instruction 11 set out only the introductory text, deleting the subparagraphs accidentally."
    },
    "q10b_doc": {
      "verdict": "yes",
      "rationale": "Identifies 2026-18800, 91 FR 58363, published and effective September 15, 2026, restoring (1)(i)-(ii)."
    },
    "q10b_reason": {
      "verdict": "yes",
      "rationale": "Gives OPM's good-cause reason: no substantive change; it restores text in effect before September 2 that OPM did not propose to remove and the final rule did not discuss removing."
    },
    "q10c_lower": {
      "verdict": "yes",
      "rationale": "Says declining a lower-representative-rate offer leaves her displaced because only a same-schedule, at-least-equal-rate offer is a qualifying offer."
    },
    "q10c_same": {
      "verdict": "yes",
      "rationale": "Says declining a same-rate, same-schedule offer makes her no longer displaced under (1)(i)."
    },
    "q10_cite": {
      "verdict": "no",
      "rationale": "The answer cites 2026-18800, 2026-15665 instruction 11, 330.602, and the relevant FR pages."
    },
    "q10_fab": {
      "verdict": "no",
      "rationale": "The quoted and paraphrased definitions match 2026-18800."
    }
  },
  "Q11": {
    "q11_valid_10": {
      "verdict": "yes",
      "rationale": "Count = 32. Item-by-item: (1) 351.202(d) heading = 1; (2) date phrases dropped in 351.202(d)(1)(ii),(d)(2)(i),(d)(2)(ii) = 3; (3) 351.202(d)(2)(iii) temporary/term/subpart C-D to temporary/subpart D = 1; (4) 351.202(d)(3) 'without regard' to specific list = 1; (5) new 351.202(d)(4) notice = 1; (6) 351.202(c)(3) 'such the' to 'such a' = 1; (7) 351.203 restoration-protected definition = 1, while the initial-probation sentence was in the proposal and is not a difference; (8) 351.204 merit-system addition = 1; (9) 351.302 'new (d)' is not counted because proposed 351.302 already had paragraph (d); (10) new 351.402(c) = 1; (11) 351.502 issue-to-receives date = 1; (12) 351.502(a)(3) subpart C/D to D = 1; (13) 351.503(a)(1) 430.208 cross-reference = 1; (14) 351.503(a)(1) 'Minimally Successful' to 'Minimally Satisfactory' = 1; (15) 351.504(a) 'should' to 'must' = 1; (16) 351.505(b)(2) cross-reference 351.503(b) to 351.504(b) = 1; (17) 351.506(c) 'their' to 'the employee's' = 1; (18) 351.506(d) added access-rights sentence = 1; (19) 351.507(b) wording = 1; (20) 351.604 proposal not finalized = 1; (21) 351.605 restructuring = 1; (22) 351.605 separate notice paragraph = 1; (23) 351.605 'may not' to 'must not' = 1; (24) 351.605 'excluded from the provisions' to 'excluded from RIF competition' = 1; (25) 351.606(a) USERRA exception = 1; (26) 351.701(a) label = 1; (27) 351.702(a)(4)(iii) wording = 1; (28) new 351.702(a)(4)(v) = 1; (29) 351.802(a) introductory text = 1; (30) 351.802(a)(2) veteran status to veterans' preference subgroup = 1; (31) new 351.805(b) = 1; (32) parts 353/362 items = 0 because outside part 351. Total 32."
    },
    "q11_valid_16": {
      "verdict": "yes",
      "rationale": "Same total as q11_valid_10: 32 valid differences."
    },
    "q11_valid_22": {
      "verdict": "yes",
      "rationale": "Same total as q11_valid_10: 32 valid differences."
    },
    "q11_valid_28": {
      "verdict": "yes",
      "rationale": "Same total as q11_valid_10: 32 valid differences."
    },
    "q11_valid_34": {
      "verdict": "no",
      "rationale": "The submission states at most 32 valid differences, below 34; the 351.302 bullet is erroneous and several key-listed differences are omitted."
    },
    "q11_deep": {
      "verdict": "yes",
      "rationale": "States at least six deep differences: 351.502 issue-vs-receive date; 351.503(a)(1)/351.701(a) Level 2 label; 351.504(a) should-to-must; 351.505(b)(2) cross-reference; 351.506(c)/(d) changes; 351.702(a)(4)(iii)/(v); and 351.802(a)(2) veterans' preference subgroup."
    },
    "q11_cite": {
      "verdict": "no",
      "rationale": "The answer identifies proposed and final text and cites FR pages and CFR paragraphs."
    },
    "q11_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation; the 351.302 error is a misreading of real text, not fabrication."
    }
  },
  "Q12": {
    "q12_quinn": {
      "verdict": "yes",
      "rationale": "Quinn is serving an initial probationary period, so she is not a competing employee and is not ranked; the agency may retain her while releasing competing employees."
    },
    "q12_ab": {
      "verdict": "yes",
      "rationale": "Alvarez 7+7+5=19; Brandt 3+5+0=8 plus 5 = 13."
    },
    "q12_chen": {
      "verdict": "yes",
      "rationale": "Chen: September 30, 2022 rating is outside the window; two ratings, proxy 6, credit 7+5+6=18."
    },
